async function loadUsers(){const ld=document.getElementById('users-loading'),tb=document.getElementById('users-table'),em=document.getElementById('users-empty');ld.style.display='block';tb.style.display='none';em.style.display='none';try{const d=await storeApi('/api/users');const owners=d.owner_emails||[];const ol=document.getElementById('owner-users-list');ol.innerHTML=owners.length===0?'<div style="color:#a0aec0;font-size:13px">No owner emails configured</div>':owners.map(e=>'<div style="display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid #f7fafc"><span style="font-size:14px">'+escHtml(e)+'</span><span class="status-badge status-shipped" style="font-size:10px">OWNER</span></div>').join('');const users=d.users||[];ld.style.display='none';if(users.length===0){em.style.display='block';return}tb.style.display='table';const bd=document.getElementById('users-body');bd.innerHTML='';users.forEach(u=>{const tr=document.createElement('tr');const dt=new Date(u.added_at).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});tr.innerHTML='<td><strong>'+escHtml(u.email)+'</strong></td><td>'+escHtml(u.name||'-')+'</td><td>'+dt+'</td><td><button class="btn btn-sm btn-danger" onclick="removeUser(\''+escHtml(u.email)+'\')" >Remove</button></td>';bd.appendChild(tr)})}catch(e){ld.innerHTML='<div class="error-text">Failed to load users: '+e.message+'</div>'}}
async function addUser(){if(exampleReadOnly())return;const emailEl=document.getElementById('add-user-email');const nameEl=document.getElementById('add-user-name');const err=document.getElementById('add-user-error');err.textContent='';const email=emailEl.value.trim();const name=nameEl.value.trim();if(!email){err.textContent='Email is required';return}try{const r=await storeApi('/api/users','POST',{email,name});if(r.error){err.textContent=r.error;return}emailEl.value='';nameEl.value='';loadUsers()}catch(e){err.textContent='Failed: '+e.message}}
async function removeUser(email){if(exampleReadOnly())return;if(!confirm('Remove access for '+email+'?'))return;try{const r=await storeApi('/api/users/'+encodeURIComponent(email),'DELETE');if(r.error){alert(r.error);return}loadUsers()}catch(e){alert('Failed: '+e.message)}}

// --- Analytics ---
let analyticsCharts={};let analyticsDateRange=30;let analyticsForecastDays=30;let analyticsData=null;
function setAnalyticsDateFilter(days,btn){analyticsDateRange=days;document.querySelectorAll('#section-analytics .controls .filter-btn').forEach(b=>b.classList.remove('active'));btn.classList.add('active');loadAnalytics()}
function setForecastPeriod(days,btn){analyticsForecastDays=days;document.querySelectorAll('.analytics-forecast-controls .filter-btn').forEach(b=>b.classList.remove('active'));btn.classList.add('active');if(analyticsData)renderForecastChart(analyticsData.time_series)}
async function loadAnalytics(){const ld=document.getElementById('analytics-loading'),ct=document.getElementById('analytics-content');ld.style.display='block';ct.style.display='none';try{const d=await storeApi('/api/analytics?days='+analyticsDateRange);analyticsData=d;renderAnalytics(d);ld.style.display='none';ct.style.display='block'}catch(e){ld.innerHTML='<div class="error-text">Failed to load analytics: '+e.message+'</div>'}}
function renderAnalytics(d){const s=d.summary;document.getElementById('an-total-revenue').innerHTML='£'+s.total_revenue.toFixed(2);document.getElementById('an-net-revenue').innerHTML='£'+s.net_revenue.toFixed(2);document.getElementById('an-refunds-sub').textContent=s.total_refunds>0?'Refunds: -£'+s.total_refunds.toFixed(2):'';document.getElementById('an-total-cost').innerHTML='£'+s.manufacture_cost.toFixed(2);document.getElementById('an-shipping-cost').innerHTML='£'+s.shipping_cost.toFixed(2);document.getElementById('an-gross-profit').innerHTML='<span class="'+(s.gross_profit>=0?'profit-positive':'profit-negative')+'">£'+s.gross_profit.toFixed(2)+'</span>';document.getElementById('an-gross-margin').innerHTML='<span class="margin-badge '+(s.gross_margin>=50?'margin-good':s.gross_margin>=20?'margin-ok':'margin-bad')+'">'+s.gross_margin.toFixed(1)+'%</span>';document.getElementById('an-avg-order').innerHTML='£'+s.avg_order_value.toFixed(2);document.getElementById('an-total-orders-sub').textContent=s.total_orders+' order'+(s.total_orders!==1?'s':'');renderRevenueChart(d.time_series);renderForecastChart(d.time_series);renderProductTable(d.products);renderCountryTable(d.countries)}
function renderRevenueChart(data){const ctx=document.getElementById('an-revenue-chart');if(analyticsCharts.revenue)analyticsCharts.revenue.destroy();analyticsCharts.revenue=new Chart(ctx,{type:'line',data:{labels:data.map(d=>d.date),datasets:[{label:'Revenue',data:data.map(d=>d.revenue),borderColor:'#4299e1',backgroundColor:'rgba(66,153,225,0.1)',fill:true,tension:0.3,pointRadius:3,borderWidth:2,yAxisID:'y'},{label:'Profit',data:data.map(d=>d.profit),borderColor:'#48bb78',backgroundColor:'rgba(72,187,120,0.1)',fill:true,tension:0.3,pointRadius:3,borderWidth:2,yAxisID:'y'},{label:'Mfg Cost',data:data.map(d=>d.manufacture_cost),borderColor:'#ed8936',backgroundColor:'rgba(237,137,54,0.05)',fill:false,tension:0.3,pointRadius:2,borderWidth:1.5,borderDash:[5,3],yAxisID:'y'},{label:'Ship Cost',data:data.map(d=>d.shipping_cost),borderColor:'#f56565',backgroundColor:'rgba(245,101,101,0.05)',fill:false,tension:0.3,pointRadius:2,borderWidth:1.5,borderDash:[5,3],yAxisID:'y'}]},options:{responsive:true,interaction:{mode:'index',intersect:false},plugins:{tooltip:{callbacks:{label:function(ctx){return ctx.dataset.label+': £'+ctx.parsed.y.toFixed(2)}}}},scales:{y:{beginAtZero:true,grid:{color:'#e2e8f0'},ticks:{callback:v=>'£'+v}},x:{grid:{display:false}}}}})}
function renderForecastChart(data){const ctx=document.getElementById('an-forecast-chart');if(analyticsCharts.forecast)analyticsCharts.forecast.destroy();if(data.length<2){document.getElementById('an-forecast-summary').textContent='Not enough data to forecast.';analyticsCharts.forecast=new Chart(ctx,{type:'line',data:{labels:[],datasets:[]},options:{responsive:true}});return}const revenues=data.map(d=>d.revenue);const n=revenues.length;let sumX=0,sumY=0,sumXY=0,sumXX=0;for(let i=0;i<n;i++){sumX+=i;sumY+=revenues[i];sumXY+=i*revenues[i];sumXX+=i*i}const slope=(n*sumXY-sumX*sumY)/(n*sumXX-sumX*sumX);const intercept=(sumY-slope*sumX)/n;const forecastDays=analyticsForecastDays;const historicalLabels=data.map(d=>d.date);const historicalRevenue=revenues;const forecastLabels=[];const forecastRevenue=[];const lastDate=new Date(data[data.length-1].date);for(let i=1;i<=forecastDays;i++){const d=new Date(lastDate);d.setDate(d.getDate()+i);forecastLabels.push(d.toISOString().split('T')[0]);const predicted=Math.max(0,intercept+slope*(n-1+i));forecastRevenue.push(Math.round(predicted*100)/100)}const allLabels=[...historicalLabels,...forecastLabels];const histData=historicalRevenue.map(v=>v);const foreData=new Array(historicalRevenue.length).fill(null);foreData[foreData.length-1]=historicalRevenue[historicalRevenue.length-1];foreData.push(...forecastRevenue);analyticsCharts.forecast=new Chart(ctx,{type:'line',data:{labels:allLabels,datasets:[{label:'Actual Revenue',data:histData.concat(new Array(forecastDays).fill(null)),borderColor:'#4299e1',backgroundColor:'rgba(66,153,225,0.1)',fill:true,tension:0.3,pointRadius:2,borderWidth:2},{label:'Forecast',data:foreData,borderColor:'#9f7aea',backgroundColor:'rgba(159,122,234,0.1)',fill:true,tension:0.3,pointRadius:2,borderWidth:2,borderDash:[6,3]}]},options:{responsive:true,interaction:{mode:'index',intersect:false},plugins:{tooltip:{callbacks:{label:function(ctx){if(ctx.parsed.y===null)return null;return ctx.dataset.label+': £'+ctx.parsed.y.toFixed(2)}}}},scales:{y:{beginAtZero:true,grid:{color:'#e2e8f0'},ticks:{callback:v=>'£'+v}},x:{grid:{display:false}}}}});const projectedTotal=forecastRevenue.reduce((s,v)=>s+v,0);const dailyAvg=projectedTotal/forecastDays;const summary=document.getElementById('an-forecast-summary');summary.innerHTML='Projected revenue over next '+forecastDays+' days: <strong>£'+projectedTotal.toFixed(2)+'</strong> (avg £'+dailyAvg.toFixed(2)+'/day). Trend: <strong>'+(slope>=0?'↑ Growing':'↓ Declining')+'</strong> at £'+Math.abs(slope).toFixed(2)+'/day.'}
function renderProductTable(products){const tb=document.getElementById('an-product-body');const em=document.getElementById('an-product-empty');const tbl=document.getElementById('an-product-table');if(products.length===0){tbl.style.display='none';em.style.display='block';return}tbl.style.display='table';em.style.display='none';tb.innerHTML='';products.forEach(p=>{const tr=document.createElement('tr');const profitCls=p.profit>=0?'profit-positive':'profit-negative';const marginCls=p.margin>=50?'margin-good':p.margin>=20?'margin-ok':'margin-bad';tr.innerHTML='<td><strong>'+escHtml(p.name)+'</strong></td><td>'+p.units_sold+'</td><td>£'+p.revenue.toFixed(2)+'</td><td>£'+p.total_cost.toFixed(2)+'</td><td class="'+profitCls+'">£'+p.profit.toFixed(2)+'</td><td><span class="margin-badge '+marginCls+'">'+p.margin.toFixed(1)+'%</span></td>';tb.appendChild(tr)})}
function renderCountryTable(countries){const ct=document.getElementById('an-country-table');const em=document.getElementById('an-country-empty');if(countries.length===0){ct.innerHTML='';em.style.display='block';return}em.style.display='none';ct.innerHTML=countries.map(c=>'<div class="country-row-analytics"><div class="country-info"><span style="font-size:20px">'+countryFlag(c.country)+'</span><span><strong>'+escHtml(c.country)+'</strong></span></div><div class="country-stats"><span>'+c.orders+' order'+(c.orders!==1?'s':'')+'</span><span>£'+c.revenue.toFixed(2)+'</span></div></div>').join('')}

// --- QR Code Tools ---
function generateQR(){
    const url=document.getElementById('qr-url').value.trim();
    const size=parseInt(document.getElementById('qr-size').value);
    if(!url){alert('Enter a URL');return}
    const qr=qrcode(0,'M');
    qr.addData(url);
    qr.make();
    const canvas=document.getElementById('qr-canvas');
    const count=qr.getModuleCount();
    const cellSize=Math.floor(size/count);
    const realSize=cellSize*count;
    canvas.width=realSize;
    canvas.height=realSize;
    const ctx=canvas.getContext('2d');
    ctx.fillStyle='#ffffff';
    ctx.fillRect(0,0,realSize,realSize);
    ctx.fillStyle='#000000';
    for(let r=0;r<count;r++)for(let c=0;c<count;c++)if(qr.isDark(r,c))ctx.fillRect(c*cellSize,r*cellSize,cellSize,cellSize);
    document.getElementById('qr-output').style.display='block';
    document.getElementById('qr-url-label').textContent=url;
}
function downloadQR(format){
    const url=document.getElementById('qr-url').value.trim();
    const size=parseInt(document.getElementById('qr-size').value);
    if(!url)return;
    if(format==='png'){
        const canvas=document.getElementById('qr-canvas');
        const link=document.createElement('a');
        link.download='fpvgate-quickstart-qr.png';
        link.href=canvas.toDataURL('image/png');
        link.click();
    } else if(format==='svg'){
        const qr=qrcode(0,'M');
        qr.addData(url);
        qr.make();
        const svgStr=qr.createSvgTag({cellSize:Math.floor(size/qr.getModuleCount()),margin:0});
        const blob=new Blob([svgStr],{type:'image/svg+xml'});
        const link=document.createElement('a');
        link.download='fpvgate-quickstart-qr.svg';
        link.href=URL.createObjectURL(blob);
        link.click();
        URL.revokeObjectURL(link.href);
    }
}

// --- URL Shortener ---
function generateRandomSlug(){
    const chars='abcdefghijkmnpqrstuvwxyz23456789';
    let s='';
    for(let i=0;i<6;i++)s+=chars[Math.floor(Math.random()*chars.length)];
    return s;
}
async function createShortUrl(){if(exampleReadOnly())return;
    const dest=document.getElementById('short-url-dest').value.trim();
    const slugInput=document.getElementById('short-url-slug').value.trim();
    const err=document.getElementById('short-url-error');
    const result=document.getElementById('short-url-result');
    err.textContent='';result.style.display='none';
    if(!dest){err.textContent='Enter a destination URL';return}
    try{new URL(dest)}catch(e){err.textContent='Enter a valid URL';return}
    const slug=slugInput||generateRandomSlug();
    try{
        const r=await storeApi('/api/urls','POST',{slug,url:dest});
        if(r.error){err.textContent=r.error;return}
        const shortUrl='https://fpvgate.xyz/'+r.slug;
        document.getElementById('short-url-value').textContent=shortUrl;
        result.style.display='block';
        document.getElementById('short-url-dest').value='';
        document.getElementById('short-url-slug').value='';
        loadShortUrls();
    }catch(e){err.textContent='Failed: '+e.message}
}
function copyShortUrl(){
    const url=document.getElementById('short-url-value').textContent;
    const btn=document.getElementById('short-url-copy-btn');
    navigator.clipboard.writeText(url).then(()=>{
        btn.textContent='Copied!';
        setTimeout(()=>btn.textContent='Copy',2000);
    }).catch(()=>{
        const ta=document.createElement('textarea');
        ta.value=url;document.body.appendChild(ta);ta.select();
        document.execCommand('copy');document.body.removeChild(ta);
        btn.textContent='Copied!';
        setTimeout(()=>btn.textContent='Copy',2000);
    });
}
async function loadShortUrls(){
    const ld=document.getElementById('short-urls-loading'),tb=document.getElementById('short-urls-table'),em=document.getElementById('short-urls-empty');
    ld.style.display='block';tb.style.display='none';em.style.display='none';
    try{
        const d=await storeApi('/api/urls');
        const urls=d.urls||[];
        ld.style.display='none';
        if(urls.length===0){em.style.display='block';return}
        tb.style.display='table';
        const bd=document.getElementById('short-urls-body');
        bd.innerHTML='';
        urls.forEach(u=>{
            const tr=document.createElement('tr');
            const short='fpvgate.xyz/'+escHtml(u.slug);
            const dt=u.created_at?new Date(u.created_at).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'-';
            tr.innerHTML=`<td><strong>${short}</strong></td><td style="max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap"><a href="${escHtml(u.url)}" target="_blank" style="color:#4299e1;text-decoration:none">${escHtml(u.url)}</a></td><td>${u.clicks||0}</td><td>${dt}</td><td><button class="btn btn-sm btn-secondary" onclick="copyUrlValue('https://${short}')">Copy</button> <button class="btn btn-sm btn-danger" onclick="deleteShortUrl('${escHtml(u.slug)}')">Delete</button></td>`;
            bd.appendChild(tr);
        });
    }catch(e){ld.innerHTML=`<div class="error-text">Failed to load: ${e.message}</div>`}
}
function copyUrlValue(url){
    navigator.clipboard.writeText(url).then(()=>{
        const btn=event.target;btn.textContent='Copied!';
        setTimeout(()=>btn.textContent='Copy',2000);
    }).catch(()=>{
        const ta=document.createElement('textarea');
        ta.value=url;document.body.appendChild(ta);ta.select();
        document.execCommand('copy');document.body.removeChild(ta);
        const btn=event.target;btn.textContent='Copied!';
        setTimeout(()=>btn.textContent='Copy',2000);
    });
}
async function deleteShortUrl(slug){if(exampleReadOnly())return;
    if(!confirm('Delete short URL fpvgate.xyz/'+slug+'?'))return;
    try{
        const r=await storeApi('/api/urls/'+encodeURIComponent(slug),'DELETE');
        if(r.error){alert(r.error);return}
        loadShortUrls();
    }catch(e){alert('Failed: '+e.message)}
}

